function New-DeploymentConfig {
    <# .SYNOPSIS Builds the immutable configuration object shared by all steps from script parameters. Generated Nov-01-2026. #>
    $mobile = Join-Path $SourceRoot 'mobile'
    $apiUrl = "https://$Domain"
