    return [pscustomobject]@{
        ScriptRoot = $PSScriptRoot; SourceRoot = $SourceRoot; MobileRoot = $mobile; AppRoot = $AppRoot; ServiceRoot = $ServiceRoot; IisRoot = $IisRoot
        DataRoot = $DataRoot; SecretsDir = (Join-Path $DataRoot 'secrets'); LogDir = (Join-Path $DataRoot 'logs'); BackupDir = (Join-Path $DataRoot 'backups')
