}

function Get-DeployCheck {
    <# .SYNOPSIS Read-only detection of every Deploy prerequisite (Node, psql, IIS, URL Rewrite, ARR, WinSW, service, certificate, port). Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $WhatIfPreference = $false   # read-only detection must not be tagged "What if" (module autoload aliases)
    $node = Get-NodeInfo
    if (-not $node) { Add-CheckResult 'Node.js 24.13+ x64' MISSING 'not found' }
    elseif ($node.Ok) { Add-CheckResult 'Node.js 24.13+ x64' OK "$($node.Version) $($node.Architecture) at $($node.Path)"; $Config.NodePath = $node.Path }
    else { Add-CheckResult 'Node.js 24.13+ x64' MISSING "found $($node.Version) $($node.Architecture) at $($node.Path)" }
    if ($node -and -not $node.UnderProgramFiles) { Add-CheckResult 'Node location' WARN 'Node is outside Program Files; LocalService may not be able to execute it.' }
    $psql = Get-PsqlInfo -OverridePath $PsqlPath
    if ($psql) { Add-CheckResult 'PostgreSQL psql (15+)' $(if ($psql.Major -ge 15) { 'OK' } else { 'MISSING' }) "$($psql.Text) at $($psql.Path)"; $Config.PsqlPath = $psql.Path; $Config.PsqlMajor = $psql.Major }
    else { Add-CheckResult 'PostgreSQL psql (15+)' MISSING 'psql.exe not found; this script never installs/replaces PostgreSQL. Install the client tools or pass -PsqlPath.' }
    $pg = Get-Service -Name 'postgresql*' -ErrorAction SilentlyContinue | Select-Object -First 1
    Add-CheckResult 'PostgreSQL service' $(if ($pg) { 'OK' } else { 'WARN' }) $(if ($pg) { "$($pg.Name) $($pg.Status)" } else { 'no postgresql* service on this host (remote server?)' })
    $iis = Get-IisPrerequisiteState
    Add-CheckResult 'IIS role' $(if ($iis.IisInstalled -and $iis.WebAdministration) { 'OK' } else { 'MISSING' }) "InetStp=$($iis.IisInstalled) WebAdministration=$($iis.WebAdministration)"
    Add-CheckResult 'IIS URL Rewrite 2' $(if ($iis.UrlRewrite) { 'OK' } else { 'MISSING' })
    Add-CheckResult 'IIS ARR 3' $(if ($iis.Arr) { 'OK' } else { 'MISSING' })
    if ($WinSWPath) {
        try { Test-WinSWBinary -Path $WinSWPath -ExpectedSha256 $WinSWSha256 | Out-Null; Add-CheckResult 'WinSW binary' OK $WinSWPath } catch { Add-CheckResult 'WinSW binary' MISSING $_.Exception.Message }
    } else { Add-CheckResult 'WinSW binary' MISSING 'supply -WinSWPath (and -WinSWSha256 unless Authenticode-signed); WinSW publishes no checksums so this script will not download it' }
    $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    Add-CheckResult "Service $ServiceName" INFO $(if ($svc) { "present ($($svc.Status))" } else { 'not installed yet' })
    Add-CheckResult 'Runtime env file' INFO $(if (Test-Path -LiteralPath $Config.EnvFile) { 'exists (never overwritten)' } else { 'will be created' })
    $listener = [Net.NetworkInformation.IPGlobalProperties]::GetIPGlobalProperties().GetActiveTcpListeners() | Where-Object { $_.Port -eq $ApiPort }
    if ($listener -and -not $svc) { Add-CheckResult "Port $ApiPort" WARN 'already in use by another process' }
    if (Test-Path HKLM:\SOFTWARE\Microsoft\InetStp) {
        $certs = @(Get-ChildItem Cert:\LocalMachine\My -ErrorAction SilentlyContinue | Where-Object {
            (Test-HttpsCertificate -Certificate $_ -Domain $Domain -CloudflareProxy:$Config.CloudflareProxy -ScriptRoot $Config.ScriptRoot).Count -eq 0 -and
            (-not $Config.CertificateThumbprint -or $_.Thumbprint -eq ($Config.CertificateThumbprint -replace '\s', ''))
        })
        Add-CheckResult "Certificate for $Domain" $(if ($certs) { 'OK' } else { 'MISSING' }) $(if ($certs) { ($certs.Thumbprint -join ', ') } else { 'none valid in LocalMachine\My; provide -PfxPath/-CertificateThumbprint' })
    }
    Add-CheckResult 'Elevated session' $(if (Test-IsAdministrator) { 'OK' } else { 'WARN' }) 'required for Deploy'
}

function Get-AndroidCheck {
    <# .SYNOPSIS Read-only detection of the Android build toolchain and project requirements. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    $WhatIfPreference = $false
    $node = Get-NodeInfo
    Add-CheckResult 'Node.js 24.13+ x64 (build)' $(if ($node -and $node.Ok) { 'OK' } else { 'MISSING' }) $(if ($node) { "$($node.Version)" })
    if ($node) { $Config.NodePath = $node.Path }
    $req = $null
    try {
        $req = Get-AndroidProjectRequirements -Config $Config
        Add-CheckResult 'Project SDK levels' OK "min $($req.MinSdk) target $($req.TargetSdk) compile $($req.CompileSdk) build-tools $($req.BuildTools) NDK $($req.Ndk) AGP $($req.Agp) Gradle $($req.Gradle)"
    } catch { Add-CheckResult 'Project SDK levels' MISSING $_.Exception.Message }
    $jdk = Find-Jdk -JavaHome $JavaHome
    Add-CheckResult 'Stable JDK (17/21/25)' $(if ($jdk) { 'OK' } else { 'MISSING' }) $(if ($jdk) { "JDK $($jdk.Major) at $($jdk.Home)" } else { 'none found' })
    $sdk = Find-AndroidSdkRoot -SdkRoot $AndroidSdkRoot
    if ($req) {
        $s = Get-AndroidSdkState -SdkRoot $sdk -Requirements $req
        foreach ($p in 'CmdlineTools', 'PlatformTools', 'Platform', 'BuildTools', 'Ndk', 'LicensesAccepted') { Add-CheckResult "Android SDK $p" $(if ($s.$p) { 'OK' } else { 'MISSING' }) $sdk }
    } else { Add-CheckResult 'Android SDK' INFO $sdk }
    Add-CheckResult 'Upload keystore' $(if ($KeystorePath -and (Test-Path -LiteralPath $KeystorePath)) { 'OK' } else { 'MISSING' }) $(if ($KeystorePath) { $KeystorePath } else { 'pass -KeystorePath or set GARAGE_UPLOAD_KEYSTORE' })
    Add-CheckResult 'Keystore passwords' INFO 'prompted securely, or env GARAGE_UPLOAD_STORE_PASSWORD / GARAGE_UPLOAD_KEY_PASSWORD'
    Add-CheckResult 'node_modules' $(if (Test-Path (Join-Path $SourceRoot 'node_modules\react-native')) { 'OK' } else { 'MISSING' }) 'use -InstallDependencies to run npm ci'
    return [pscustomobject]@{ Requirements = $req; Jdk = $jdk; SdkRoot = $sdk }
}

function Invoke-DeployPlan {
    [CmdletBinding(SupportsShouldProcess)]
    <# .SYNOPSIS Under -WhatIf, emits the ordered list of changes Deploy would request approval for, without prompting. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    foreach ($row in ($script:report | Where-Object Status -eq 'MISSING')) { $PSCmdlet.ShouldProcess($row.Name, 'Resolve missing prerequisite (install after approval, or stop with instructions)') | Out-Null }
    $steps = @(
        @($Config.Database, "Idempotently create roles $($Config.DeployRole)/$($Config.RuntimeRole) and the database (existing data preserved)"),
        @($Config.SecretsDir, 'Create ACL-restricted secrets/log/backup directories (SYSTEM, Administrators, LocalService only)'),
        @($Config.AppRoot, 'Back up (JSON), stop the service, additively copy source, npm ci (shared+server), build'),
        @($Config.Database, 'Run server\dist\migrate.js as garage_deploy, then grant-runtime.sql'),
        @($Config.EnvFile, 'Create runtime.env if absent (MIGRATIONS_ON_START=false); validate if present'),
        @($Config.SecretsDir, 'Optionally verify/install -LicensePublicKeyPath and set LICENSE_PUBLIC_KEY_FILE; never install a private signing key'),
        @($Config.Database, 'Bootstrap the owner only if the users table is empty'),
        @($Config.ServiceName, 'Install/refresh WinSW service as NT AUTHORITY\LocalService with generated paths; start; verify http://127.0.0.1 health'),
        @($Config.Domain, "IIS: pool/site $($Config.SiteName), http+https SNI bindings, web.config, existing certificate, ARR proxy"),
        @('GarageManager-Reminders / GarageManager-Backup', 'Register scheduled tasks as LocalService'),
        @("https://$($Config.Domain)/health", 'Verify HTTPS locally and through public DNS (fails explicitly)')
    )
    foreach ($s in $steps) { $PSCmdlet.ShouldProcess($s[0], $s[1]) | Out-Null }
}

function Invoke-Deploy {
    [CmdletBinding(SupportsShouldProcess)]
    <# .SYNOPSIS Executes the approval-gated deployment sequence. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    Write-Step 'Deploy'
    if ($WhatIfPreference) { $script:report = @(); Get-DeployCheck -Config $Config; Invoke-DeployPlan -Config $Config; return }
    if (-not (Test-IsAdministrator)) { throw 'Deploy requires an elevated (Administrator) Windows PowerShell session.' }
    if ($PSVersionTable.PSEdition -eq 'Core') { throw 'Run Deploy in Windows PowerShell 5.1 (WebAdministration module).' }
    $script:report = @(); Get-DeployCheck -Config $Config
    $missing = @($script:report | Where-Object Status -eq 'MISSING' | ForEach-Object Name)
    if ($missing -contains 'Node.js 24.13+ x64') { if (Install-NodeRuntime) { $script:report = @(); Get-DeployCheck -Config $Config } }
    if (-not $Config.NodePath) { throw 'Node.js 24.13+ x64 is required and was not installed. Stopped before any deployment change.' }
    if (-not $Config.PsqlPath -or $Config.PsqlMajor -lt 15) { throw 'PostgreSQL psql 15+ is required. Install the PostgreSQL client tools (or pass -PsqlPath); this script does not install PostgreSQL. Stopped.' }
    if (-not $Config.NodePath.StartsWith($env:ProgramFiles, [StringComparison]::OrdinalIgnoreCase)) { throw 'Node must be installed under Program Files so LocalService can run it.' }
    $iis = Get-IisPrerequisiteState
    if (-not ($iis.IisInstalled -and $iis.WebAdministration)) { Install-IisFeatures | Out-Null; throw 'IIS role features were (re)configured or declined; open a new elevated PowerShell (a reboot may be needed) and re-run Deploy.' }
    if (-not $iis.UrlRewrite) { Install-IisExtension -Name UrlRewrite | Out-Null }
    if (-not $iis.Arr) { Install-IisExtension -Name Arr | Out-Null }
    $iis = Get-IisPrerequisiteState
    if (-not ($iis.UrlRewrite -and $iis.Arr)) { throw 'URL Rewrite and ARR are required. Install them from Microsoft, then re-run. Stopped before deployment changes.' }
    if (-not $WinSWPath) {
        if (-not $DownloadWinSW) { throw 'Provide -WinSWPath (and -WinSWSha256 for an unsigned binary), or re-run with -DownloadWinSW to approve downloading the official WinSW release for you to verify. Stopped.' }
        $null = Get-WinSWDownload -Config $Config
        if (-not $Config.WinSWPath) { throw 'WinSW download was declined. Stopped.' }
    }
    Test-WinSWBinary -Path $Config.WinSWPath -ExpectedSha256 $Config.WinSWSha256 | Out-Null
    Assert-NoIisConflicts -Config $Config

    Write-Step 'Directories and ACLs'
    $admin = '*S-1-5-32-544:(OI)(CI)F'; $system = '*S-1-5-18:(OI)(CI)F'
    Set-RestrictedAcl -Path $Config.SecretsDir -Grants @($admin, $system, '*S-1-5-19:(OI)(CI)RX')
    Set-RestrictedAcl -Path $Config.LogDir -Grants @($admin, $system, '*S-1-5-19:(OI)(CI)M')
    Set-RestrictedAcl -Path $Config.BackupDir -Grants @($admin, $system, '*S-1-5-19:(OI)(CI)M')
    Set-RestrictedAcl -Path $Config.ServiceRoot -Grants @($admin, $system, '*S-1-5-19:(OI)(CI)RX')
    New-Item -ItemType Directory -Force -Path $Config.AppRoot, $Config.IisRoot | Out-Null

    Write-Step 'Database (roles, database, preserved data)'
    $adminPw = Read-SecretPrompt -Prompt "PostgreSQL administrator ($PgAdminUser) password" -EnvironmentVariable 'GARAGE_PG_ADMIN_PASSWORD'
    $deployPw = Read-SecretPrompt -Prompt 'garage_deploy password (new, or existing)' -EnvironmentVariable 'GARAGE_PG_DEPLOY_PASSWORD' -MinimumLength 12
    $state = Get-DatabaseState -Config $Config -AdminPassword $adminPw
    $needsProvision = ($state.RolesPresent -lt 2) -or -not $state.DatabasePresent
    $runtimePw = $null
    if ($needsProvision -or $HardenExistingDatabase -or -not (Test-Path -LiteralPath $Config.EnvFile)) {
        $runtimePw = Read-SecretPrompt -Prompt 'garage_runtime password (12+ characters)' -EnvironmentVariable 'GARAGE_PG_RUNTIME_PASSWORD' -MinimumLength 12
        if ((ConvertTo-PlainText $runtimePw) -ceq (ConvertTo-PlainText $deployPw)) { throw 'garage_runtime and garage_deploy must use different passwords.' }
    }
    if ($needsProvision -or $HardenExistingDatabase) {
        if (Request-Approval -Action 'Provision PostgreSQL roles/database' -Target "$PgHost`:$PgPort/$Database" -Detail "Roles present: $($state.RolesPresent)/2; database present: $($state.DatabasePresent). Existing data and passwords are not modified." -Required) {
            Invoke-DatabaseProvision -Config $Config -AdminPassword $adminPw -DeployPassword $deployPw -RuntimePassword $runtimePw -HardenExisting:$HardenExistingDatabase
        }
    } else { Write-Info 'Roles and database already exist; provisioning skipped.' }
    if (-not (Test-RoleLogin -Config $Config -User $Config.DeployRole -Password $deployPw)) { throw 'garage_deploy login failed: wrong password for the existing role.' }

    Write-Step 'Application source and build'
    $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    $exe = Join-Path $ServiceRoot "$ServiceName.exe"
    if ($svc -and -not $SkipPreDeployBackup -and (Test-Path -LiteralPath $Config.EnvFile) -and (Test-Path -LiteralPath (Join-Path $AppRoot 'server\dist\backup.js'))) {
        if (Request-Approval -Action 'Take a JSON business backup before updating' -Target $Config.BackupDir -Detail 'Uses the currently deployed Run-Backup.ps1.' -Required) {
            & (Join-Path $AppRoot 'deploy\windows\Run-Backup.ps1') -AppRoot $AppRoot -EnvironmentFile $Config.EnvFile -BackupDirectory $Config.BackupDir -NodePath $Config.NodePath
        }
    }
    if ($svc -and $svc.Status -eq 'Running') {
        if (Request-Approval -Action 'Stop the Garage service for the update' -Target $ServiceName -Required) { Invoke-Native -FilePath $exe -Arguments @('stop') | Out-Null }
    }
    if (Request-Approval -Action 'Copy source (additive, no deletions) and build the server' -Target $AppRoot -Detail "From $SourceRoot; excludes secrets, node_modules, Android folders and build output." -Required) {
        Copy-ApplicationSource -Config $Config
        Invoke-ServerBuild -Config $Config
    }

    Write-Step 'Migration, grants and runtime environment'
    Invoke-SchemaMigration -Config $Config -DeployPassword $deployPw
    Install-RuntimeEnvFile -Config $Config -RuntimePassword $runtimePw
    Install-LicensePublicKey -Config $Config
    Invoke-OwnerBootstrap -Config $Config -DeployPassword $deployPw

    Write-Step 'Windows service'
    Install-GarageService -Config $Config
    Assert-LocalServiceReadOnly -Config $Config
    Start-GarageService -Config $Config

    Write-Step 'IIS reverse proxy and HTTPS'
    Set-GarageIisSite -Config $Config
    Register-GarageTasks -Config $Config
    Test-PublicHttps -Config $Config
    Write-Host "`nDeployment complete and verified at https://$Domain/health" -ForegroundColor Green
}

function Invoke-AndroidBuild {
    [CmdletBinding(SupportsShouldProcess)]
    <# .SYNOPSIS Prepares prerequisites with approval, then builds, signs and verifies the Android release locally. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config)
    Write-Step 'Android local release build'
    $script:report = @(); $ctx = Get-AndroidCheck -Config $Config
    if ($WhatIfPreference) {
        foreach ($row in ($script:report | Where-Object Status -eq 'MISSING')) { $PSCmdlet.ShouldProcess($row.Name, 'Resolve missing prerequisite (install after approval, or stop with instructions)') | Out-Null }
        $PSCmdlet.ShouldProcess($Config.MobileRoot, 'expo prebuild, Gradle assembleRelease+bundleRelease with init-script signing, verify certificates, copy outputs') | Out-Null
        return
    }
    if (-not $Config.NodePath) { throw 'Node.js 24.13+ x64 is required (install it, e.g. via Deploy approval flow or nodejs.org). Stopped.' }
    if (-not (Test-Path (Join-Path $SourceRoot 'node_modules\react-native'))) {
        if (-not $InstallDependencies) { throw 'node_modules is missing. Re-run with -InstallDependencies (npm ci in the repo root) or run npm ci yourself.' }
        if (Request-Approval -Action 'npm ci (repository root)' -Target $SourceRoot -Required) {
            Push-Location $SourceRoot; try { Invoke-Native -FilePath (Join-Path (Split-Path $Config.NodePath) 'npm.cmd') -Arguments @('ci') -Passthru | Out-Null } finally { Pop-Location }
        }
    }
    $req = Get-AndroidProjectRequirements -Config $Config
    $jdk = $ctx.Jdk
    if (-not $jdk) {
        if (-not (Test-IsAdministrator)) { throw 'No stable JDK 17/21/25 found. Install one yourself, or re-run elevated to let this script install a verified Microsoft OpenJDK after approval.' }
        if (-not (Install-JdkRuntime -Major $JdkMajorToInstall)) { throw 'A stable JDK is required. Stopped.' }
        $jdk = Find-Jdk -JavaHome $JavaHome
        if (-not $jdk) { throw 'JDK installed but not detected; pass -JavaHome with the JDK folder.' }
    }
    $sdk = $ctx.SdkRoot
    $state = Get-AndroidSdkState -SdkRoot $sdk -Requirements $req
    if (-not $state.CmdlineTools) {
        if (-not (Install-AndroidCmdlineTools -SdkRoot $sdk)) { throw 'Android command-line tools are required. Install Android Studio or approve the official download. Stopped.' }
    }
    $state = Get-AndroidSdkState -SdkRoot $sdk -Requirements $req
    if (-not ($state.PlatformTools -and $state.Platform -and $state.BuildTools -and $state.Ndk -and $state.LicensesAccepted)) {
        if (-not (Install-AndroidSdkPackages -SdkRoot $sdk -Requirements $req -JavaHome $jdk.Home)) { throw 'Required Android SDK packages/licenses were not approved. Stopped.' }
    }
    if (-not $KeystorePath) { $KeystorePath = Read-Host 'Existing upload keystore path' }
    if (-not $KeyAlias) { $KeyAlias = Read-Host 'Upload key alias' }
    Invoke-AndroidRelease -Config $Config -Requirements $req -JavaHome $jdk.Home -SdkRoot $sdk -Keystore $KeystorePath -Alias $KeyAlias -CleanPrebuild:$CleanPrebuild
}

# Load read-only modules once with -WhatIf disabled so autoload never reports alias creation as a pending change.
$config = New-DeploymentConfig
$script:report = @()
if ($Mode -in 'Check', 'All') {
    Write-Step 'Check (read-only)'
    Get-DeployCheck -Config $config
    $android = Get-AndroidCheck -Config $config
    $script:report | Format-Table -AutoSize -Wrap | Out-Host
    $blocking = @($script:report | Where-Object Status -eq 'MISSING')
    if ($Mode -eq 'Check') {
        if ($blocking) { Write-Warning "$($blocking.Count) prerequisite(s) missing. Nothing was changed."; exit 2 }
        Write-Host 'All checked prerequisites are present. Nothing was changed.' -ForegroundColor Green
        exit 0
    }
}
if ($Mode -in 'Deploy', 'All') { Invoke-Deploy -Config $config }
if ($Mode -in 'BuildAndroid', 'All') { Invoke-AndroidBuild -Config $config }
